// Minimal Lightweight STOMP client over WebSocket for LAN application
(function(window) {
  var Stomp = {
    VERSIONS: {
      V1_0: '1.0',
      V1_1: '1.1',
      V1_2: '1.2'
    },
    client: function(url, protocols) {
      var klass = Stomp.WebSocketClient || Stomp.Client;
      return new klass(url, protocols);
    },
    over: function(ws) {
      var klass = Stomp.WebSocketClient || Stomp.Client;
      return new klass(ws);
    }
  };

  function Frame(command, headers, body) {
    this.command = command;
    this.headers = headers || {};
    this.body = body || '';
  }

  Frame.prototype.toString = function() {
    var lines = [this.command];
    for (var name in this.headers) {
      if (this.headers.hasOwnProperty(name)) {
        lines.push(name + ':' + this.headers[name]);
      }
    }
    lines.push('');
    lines.push(this.body);
    return lines.join('\n') + '\0';
  };

  Frame.unmarshall = function(datas) {
    var frames = [];
    var rawFrames = datas.split('\0');
    for (var i = 0; i < rawFrames.length; i++) {
      var chunk = rawFrames[i].trim();
      if (chunk.length === 0) continue;
      var lines = chunk.split('\n');
      var command = lines[0].trim();
      var headers = {};
      var body = '';
      var j = 1;
      for (; j < lines.length; j++) {
        var line = lines[j];
        if (line === '') {
          j++;
          break;
        }
        var idx = line.indexOf(':');
        if (idx > 0) {
          headers[line.substring(0, idx).trim()] = line.substring(idx + 1).trim();
        }
      }
      body = lines.slice(j).join('\n');
      frames.push(new Frame(command, headers, body));
    }
    return frames;
  };

  function Client(ws) {
    this.ws = typeof ws === 'string' ? new WebSocket(ws) : ws;
    this.subscriptions = {};
    this.subIdCounter = 0;
    this.connected = false;
  }

  Client.prototype.connect = function(headers, connectCallback, errorCallback) {
    var self = this;
    if (typeof headers === 'function') {
      errorCallback = connectCallback;
      connectCallback = headers;
      headers = {};
    }

    var onOpen = function() {
      var frame = new Frame('CONNECT', { 'accept-version': '1.1,1.0', 'heart-beat': '10000,10000' });
      self.ws.send(frame.toString());
    };

    var onMessage = function(evt) {
      var frames = Frame.unmarshall(evt.data);
      for (var i = 0; i < frames.length; i++) {
        var frame = frames[i];
        if (frame.command === 'CONNECTED') {
          self.connected = true;
          if (connectCallback) connectCallback(frame);
        } else if (frame.command === 'MESSAGE') {
          var subId = frame.headers['subscription'];
          if (self.subscriptions[subId]) {
            self.subscriptions[subId](frame);
          }
        } else if (frame.command === 'ERROR') {
          if (errorCallback) errorCallback(frame);
        }
      }
    };

    var onClose = function(evt) {
      self.connected = false;
      if (errorCallback) errorCallback(evt);
    };

    if (this.ws.readyState === 1) {
      onOpen();
    } else {
      this.ws.onopen = onOpen;
    }
    this.ws.onmessage = onMessage;
    this.ws.onclose = onClose;
    this.ws.onerror = onClose;
  };

  Client.prototype.subscribe = function(destination, callback, headers) {
    headers = headers || {};
    var subId = 'sub-' + (this.subIdCounter++);
    headers['id'] = subId;
    headers['destination'] = destination;
    this.subscriptions[subId] = callback;

    var frame = new Frame('SUBSCRIBE', headers);
    this.ws.send(frame.toString());

    var self = this;
    return {
      id: subId,
      unsubscribe: function() {
        delete self.subscriptions[subId];
        var unSubFrame = new Frame('UNSUBSCRIBE', { id: subId });
        self.ws.send(unSubFrame.toString());
      }
    };
  };

  Client.prototype.send = function(destination, headers, body) {
    headers = headers || {};
    headers['destination'] = destination;
    var frame = new Frame('SEND', headers, body || '');
    this.ws.send(frame.toString());
  };

  Client.prototype.disconnect = function(disconnectCallback) {
    try {
      var frame = new Frame('DISCONNECT');
      this.ws.send(frame.toString());
      this.ws.close();
    } catch(e){}
    this.connected = false;
    if (disconnectCallback) disconnectCallback();
  };

  Stomp.Client = Client;
  window.Stomp = Stomp;
})(window);
